import { useState, useEffect, useCallback, useRef } from 'react';
import { flattenCollections } from '@isoflow/isopacks/dist/utils';

// Built-in icon packs (lazy-loaded from @isoflow/isopacks)
export type IconPackName = 'aws' | 'gcp' | 'azure' | 'kubernetes';

// Any pack id: built-in, or a custom pack from icon-packs.generated.json
// (generated by scripts/generate-icon-packs.mjs from the icon-packs/ folder)
export type PackId = IconPackName | (string & {});

const BUILTIN_PACKS: IconPackName[] = ['aws', 'gcp', 'azure', 'kubernetes'];

export interface IconPackInfo {
  name: string;
  displayName: string;
  loaded: boolean;
  loading: boolean;
  error: string | null;
  iconCount: number;
  /** true if this pack comes from the user's icon-packs/ folder */
  custom: boolean;
  /** true if this pack was imported at runtime via the settings UI */
  imported?: boolean;
}

export interface CustomPackIcon {
  id: string;
  name: string;
  url: string;
  isIsometric?: boolean;
  scale?: number;
}

export interface CustomPackDef {
  id: string;
  name: string;
  isIsometric: boolean;
  icons: CustomPackIcon[];
  /** true for packs imported at runtime (persisted in IndexedDB) */
  imported?: boolean;
  createdAt?: string;
}

interface GeneratedPacksFile {
  generatedAt?: string;
  packs?: CustomPackDef[];
}

// localStorage keys
const LAZY_LOADING_KEY = 'fossflow-lazy-loading-enabled';
const ENABLED_PACKS_KEY = 'fossflow-enabled-icon-packs';
// Custom packs are enabled as soon as they are generated; this key records
// the ones the user explicitly switched off, so they stay off after reload.
const DISABLED_CUSTOM_PACKS_KEY = 'fossflow-disabled-custom-packs';

// Pack metadata
const PACK_METADATA: Record<IconPackName, string> = {
  aws: 'AWS Icons',
  gcp: 'Google Cloud Icons',
  azure: 'Azure Icons',
  kubernetes: 'Kubernetes Icons'
};

// Load preferences from localStorage
export const loadLazyLoadingPreference = (): boolean => {
  const stored = localStorage.getItem(LAZY_LOADING_KEY);
  return stored === null ? true : stored === 'true'; // Default to true
};

export const saveLazyLoadingPreference = (enabled: boolean): void => {
  localStorage.setItem(LAZY_LOADING_KEY, String(enabled));
};

export const loadEnabledPacks = (): IconPackName[] => {
  const stored = localStorage.getItem(ENABLED_PACKS_KEY);
  if (!stored) return [];
  try {
    return JSON.parse(stored) as IconPackName[];
  } catch {
    return [];
  }
};

export const saveEnabledPacks = (packs: IconPackName[]): void => {
  localStorage.setItem(ENABLED_PACKS_KEY, JSON.stringify(packs));
};

export const loadDisabledCustomPacks = (): string[] => {
  const stored = localStorage.getItem(DISABLED_CUSTOM_PACKS_KEY);
  if (!stored) return [];
  try {
    return JSON.parse(stored) as string[];
  } catch {
    return [];
  }
};

export const saveDisabledCustomPacks = (packs: string[]): void => {
  localStorage.setItem(DISABLED_CUSTOM_PACKS_KEY, JSON.stringify(packs));
};

// Base URL prefix for static assets (handles deployments under a sub-path)
const getAssetPrefix = (): string => {
  const env =
    typeof import.meta !== 'undefined' && (import.meta as any).env
      ? (import.meta as any).env
      : {};
  const prefix: string = env.ASSET_PREFIX || env.PUBLIC_URL || '/';
  return prefix.endsWith('/') ? prefix : `${prefix}/`;
};

// Fetch the generated custom packs manifest (null when absent/broken)
export const fetchCustomPacks = async (): Promise<CustomPackDef[] | null> => {
  try {
    // cache-bust: guarantees a simple page refresh picks up newly generated packs
    const res = await fetch(
      `${getAssetPrefix()}icon-packs.generated.json?t=${Date.now()}`
    );
    if (!res.ok) return null;
    const data = (await res.json()) as GeneratedPacksFile;
    if (!data || !Array.isArray(data.packs)) return null;
    return data.packs.filter((p) => {
      return p && typeof p.id === 'string' && Array.isArray(p.icons);
    });
  } catch {
    return null;
  }
};

// ---------------------------------------------------------------------------
// IndexedDB storage for imported icon packs (persist across restarts)
// ---------------------------------------------------------------------------
const IDB_NAME = 'fossflow-icon-packs';
const IDB_VERSION = 1;
const IDB_STORE = 'packs';

const openIdb = (): Promise<IDBDatabase | null> => {
  return new Promise((resolve) => {
    if (typeof indexedDB === 'undefined') {
      resolve(null);
      return;
    }
    try {
      const req = indexedDB.open(IDB_NAME, IDB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(IDB_STORE)) {
          db.createObjectStore(IDB_STORE, { keyPath: 'id' });
        }
      };
      req.onsuccess = () => {
        return resolve(req.result);
      };
      req.onerror = () => {
        return resolve(null);
      };
    } catch {
      resolve(null);
    }
  });
};

const idbListPacks = async (): Promise<CustomPackDef[]> => {
  const db = await openIdb();
  if (!db) return [];
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(IDB_STORE, 'readonly');
      const req = tx.objectStore(IDB_STORE).getAll();
      req.onsuccess = () => {
        resolve(
          ((req.result as CustomPackDef[]) || []).filter((p) => {
            return p && typeof p.id === 'string' && Array.isArray(p.icons);
          })
        );
      };
      req.onerror = () => {
        return resolve([]);
      };
    } catch {
      resolve([]);
    }
  });
};

const idbSavePack = async (pack: CustomPackDef): Promise<void> => {
  const db = await openIdb();
  if (!db) throw new Error('IndexedDB unavailable');
  return new Promise((resolve, reject) => {
    try {
      const tx = db.transaction(IDB_STORE, 'readwrite');
      tx.objectStore(IDB_STORE).put(pack);
      tx.oncomplete = () => {
        return resolve();
      };
      tx.onerror = () => {
        return reject(tx.error || new Error('IndexedDB write failed'));
      };
    } catch (e) {
      reject(e);
    }
  });
};

const idbDeletePack = async (packId: string): Promise<void> => {
  const db = await openIdb();
  if (!db) return;
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(IDB_STORE, 'readwrite');
      tx.objectStore(IDB_STORE).delete(packId);
      tx.oncomplete = () => {
        return resolve();
      };
      tx.onerror = () => {
        return resolve();
      };
    } catch {
      resolve();
    }
  });
};

// Dynamic pack loader (built-in packs only)
export const loadIconPack = async (packName: IconPackName): Promise<any> => {
  switch (packName) {
    case 'aws':
      return (await import('@isoflow/isopacks/dist/aws')).default;
    case 'gcp':
      return (await import('@isoflow/isopacks/dist/gcp')).default;
    case 'azure':
      return (await import('@isoflow/isopacks/dist/azure')).default;
    case 'kubernetes':
      return (await import('@isoflow/isopacks/dist/kubernetes')).default;
    default:
      throw new Error(`Unknown icon pack: ${packName}`);
  }
};

// Wrap a custom pack definition in the same shape as a built-in isopack so it
// can go through flattenCollections() like any other pack.
const buildCustomPackObject = (def: CustomPackDef): any => {
  return {
    id: def.id,
    name: def.name,
    icons: def.icons.map((icon) => {
      return {
        id: icon.id,
        name: icon.name,
        url: icon.url,
        isIsometric: icon.isIsometric === true || def.isIsometric === true
      };
    })
  };
};

// React hook for managing icon packs (built-in + custom)
export const useIconPackManager = (coreIcons: any[]) => {
  const [lazyLoadingEnabled, setLazyLoadingEnabled] = useState<boolean>(() =>
    loadLazyLoadingPreference()
  );

  const [enabledPacks, setEnabledPacks] = useState<IconPackName[]>(() =>
    loadEnabledPacks()
  );

  const [disabledCustomPacks, setDisabledCustomPacks] = useState<string[]>(() =>
    loadDisabledCustomPacks()
  );

  const [packInfo, setPackInfo] = useState<Record<string, IconPackInfo>>(() => {
    const info: Record<string, IconPackInfo> = {};
    BUILTIN_PACKS.forEach((name) => {
      info[name] = {
        name,
        displayName: PACK_METADATA[name],
        loaded: false,
        loading: false,
        error: null,
        iconCount: 0,
        custom: false
      };
    });
    return info;
  });

  const [loadedIcons, setLoadedIcons] = useState<any[]>(coreIcons);
  const [loadedPackData, setLoadedPackData] = useState<Record<string, any[]>>({});

  // Latest custom pack definitions (kept in a ref so async init does not
  // depend on stale state closures)
  const customPacksRef = useRef<Record<string, CustomPackDef>>({});

  const isCustomPack = useCallback(
    (packName: string) => {
      return customPacksRef.current[packName] !== undefined;
    },
    []
  );

  // Load a specific pack (built-in or custom)
  const loadPack = useCallback(async (packName: string) => {
    // Already loaded?
    if (packInfo[packName]?.loaded || packInfo[packName]?.loading) {
      return;
    }

    // Set loading state
    setPackInfo((prev) => {
      return {
        ...prev,
        [packName]: prev[packName]
          ? { ...prev[packName], loading: true, error: null }
          : {
              name: packName,
              displayName: packName,
              loaded: false,
              loading: true,
              error: null,
              iconCount: 0,
              custom: isCustomPack(packName)
            }
      };
    });

    try {
      let pack: any;
      if (BUILTIN_PACKS.includes(packName as IconPackName)) {
        pack = await loadIconPack(packName as IconPackName);
      } else {
        const def = customPacksRef.current[packName];
        if (!def) throw new Error(`Unknown custom icon pack: ${packName}`);
        pack = buildCustomPackObject(def);
      }

      const flattenedIcons = flattenCollections([pack]);

      // Store the flattened pack data (used when rebuilding the icon list)
      setLoadedPackData((prev) => {
        return { ...prev, [packName]: flattenedIcons };
      });

      // Update pack info
      setPackInfo((prev) => {
        return {
          ...prev,
          [packName]: {
            ...(prev[packName] || {
              name: packName,
              displayName: packName,
              custom: isCustomPack(packName)
            }),
            name: packName,
            loaded: true,
            loading: false,
            iconCount: flattenedIcons.length,
            error: null
          }
        };
      });

      // Add icons to the loaded icons array
      setLoadedIcons((prev) => [...prev, ...flattenedIcons]);

      return flattenedIcons;
    } catch (error) {
      console.error(`Failed to load ${packName} icon pack:`, error);
      setPackInfo((prev) => {
        return {
          ...prev,
          [packName]: {
            ...(prev[packName] || {
              name: packName,
              displayName: packName,
              iconCount: 0,
              custom: isCustomPack(packName)
            }),
            name: packName,
            loading: false,
            error: error instanceof Error ? error.message : 'Failed to load pack'
          }
        };
      });
      throw error;
    }
  }, [packInfo, isCustomPack]);

  // Keep a ref to the latest loadPack so one-time async init can call it
  // without stale-closure issues
  const loadPackRef = useRef(loadPack);
  useEffect(() => {
    loadPackRef.current = loadPack;
  });

  // Rebuild the loaded icons array from core icons + currently active packs
  const rebuildIcons = useCallback(
    (
      builtinEnabled: IconPackName[],
      customDisabled: string[]
    ) => {
      const activeIcons: any[] = [...coreIcons];
      Object.keys(loadedPackData).forEach((packName) => {
        const isActive = BUILTIN_PACKS.includes(packName as IconPackName)
          ? builtinEnabled.includes(packName as IconPackName)
          : !customDisabled.includes(packName);
        if (isActive) {
          activeIcons.push(...loadedPackData[packName]);
        }
      });
      setLoadedIcons(activeIcons);
    },
    [coreIcons, loadedPackData]
  );

  // Enable/disable a pack (built-in or custom)
  const togglePack = useCallback(
    async (packName: string, enabled: boolean) => {
      if (BUILTIN_PACKS.includes(packName as IconPackName)) {
        if (enabled) {
          const newEnabledPacks = [...new Set([...enabledPacks, packName as IconPackName])];
          setEnabledPacks(newEnabledPacks);
          saveEnabledPacks(newEnabledPacks);
          await loadPack(packName);
        } else {
          const newEnabledPacks = enabledPacks.filter((p) => {
            return p !== packName;
          });
          setEnabledPacks(newEnabledPacks);
          saveEnabledPacks(newEnabledPacks);
          rebuildIcons(newEnabledPacks, disabledCustomPacks);
        }
        return;
      }

      // Custom pack
      if (enabled) {
        const newDisabled = disabledCustomPacks.filter((p) => {
          return p !== packName;
        });
        setDisabledCustomPacks(newDisabled);
        saveDisabledCustomPacks(newDisabled);
        await loadPack(packName);
      } else {
        const newDisabled = [...new Set([...disabledCustomPacks, packName])];
        setDisabledCustomPacks(newDisabled);
        saveDisabledCustomPacks(newDisabled);
        rebuildIcons(enabledPacks, newDisabled);
      }
    },
    [enabledPacks, disabledCustomPacks, loadPack, rebuildIcons]
  );

  // Toggle lazy loading
  const toggleLazyLoading = useCallback((enabled: boolean) => {
    setLazyLoadingEnabled(enabled);
    saveLazyLoadingPreference(enabled);
  }, []);

  // Load all packs (for when lazy loading is disabled)
  const loadAllPacks = useCallback(async () => {
    const allPacks: string[] = [
      ...BUILTIN_PACKS,
      ...Object.keys(customPacksRef.current)
    ];
    for (const pack of allPacks) {
      if (!packInfo[pack]?.loaded && !packInfo[pack]?.loading) {
        await loadPack(pack);
      }
    }
  }, [packInfo, loadPack]);

  // Auto-detect required packs from diagram data
  const loadPacksForDiagram = useCallback(
    async (diagramItems: any[]) => {
      if (!diagramItems || diagramItems.length === 0) return;

      // Extract unique collections from diagram items
      const collections = new Set<string>();
      diagramItems.forEach((item) => {
        if (item.icon?.collection) {
          collections.add(item.icon.collection);
        }
      });

      for (const collection of collections) {
        if (collection === 'isoflow' || collection === 'imported') continue;

        const isBuiltin = BUILTIN_PACKS.includes(collection as IconPackName);
        const isCustom = customPacksRef.current[collection] !== undefined;
        if (!isBuiltin && !isCustom) continue;

        if (isBuiltin) {
          const packName = collection as IconPackName;
          if (!packInfo[packName].loaded && !packInfo[packName].loading) {
            await loadPack(packName);
          }
          if (!enabledPacks.includes(packName)) {
            const newEnabledPacks = [...enabledPacks, packName];
            setEnabledPacks(newEnabledPacks);
            saveEnabledPacks(newEnabledPacks);
          }
        } else {
          // Custom pack: re-enable + load so old diagrams keep working
          const packName = collection;
          if (!packInfo[packName]?.loaded && !packInfo[packName]?.loading) {
            await loadPack(packName);
          }
          if (disabledCustomPacks.includes(packName)) {
            const newDisabled = disabledCustomPacks.filter((p) => {
              return p !== packName;
            });
            setDisabledCustomPacks(newDisabled);
            saveDisabledCustomPacks(newDisabled);
          }
        }
      }
    },
    [packInfo, enabledPacks, disabledCustomPacks, loadPack]
  );

  // Import local image files as a new persistent custom pack (IndexedDB)
  const importIconFiles = useCallback(
    async (files: File[], packName?: string) => {
      const images = files.filter((f) => {
        return /\.(png|jpe?g|webp|gif|svg)$/i.test(f.name);
      });
      if (images.length === 0) {
        throw new Error('No PNG/SVG/WEBP/JPG images found in the selection');
      }

      const packId = `imported-${Date.now().toString(36)}-${Math.random()
        .toString(36)
        .slice(2, 6)}`;
      const sanitize = (s: string) => s.replace(/[^a-zA-Z0-9._-]+/g, '_');

      const icons: CustomPackIcon[] = [];
      for (const file of images) {
        const url = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => {
            return resolve(String(reader.result));
          };
          reader.onerror = () => {
            return reject(new Error(`Failed to read ${file.name}`));
          };
          reader.readAsDataURL(file);
        });
        const stem = file.name.replace(/\.[^.]+$/, '');
        icons.push({
          id: `${packId}-${sanitize(stem)}`,
          name: stem.replace(/[-_]+/g, ' ').trim().slice(0, 100) || stem,
          url,
          // Imported images stand upright on the grid (3D look) by default
          isIsometric: true
        });
      }

      const def: CustomPackDef = {
        id: packId,
        name: (packName || 'Imported Icons').slice(0, 100),
        isIsometric: true,
        imported: true,
        createdAt: new Date().toISOString(),
        icons
      };

      // Persist first so a failed write does not leave a half-registered pack
      await idbSavePack(def);

      customPacksRef.current[packId] = def;
      const flattenedIcons = flattenCollections([buildCustomPackObject(def)]);

      setLoadedPackData((prev) => {
        return { ...prev, [packId]: flattenedIcons };
      });
      setPackInfo((prev) => {
        return {
          ...prev,
          [packId]: {
            name: packId,
            displayName: def.name,
            loaded: true,
            loading: false,
            error: null,
            iconCount: icons.length,
            custom: true,
            imported: true
          }
        };
      });
      setLoadedIcons((prev) => [...prev, ...flattenedIcons]);
    },
    []
  );

  // Delete an imported custom pack (and its persisted IndexedDB record)
  const deletePack = useCallback(
    async (packName: string) => {
      const def = customPacksRef.current[packName];
      if (!def || !def.imported) return;

      delete customPacksRef.current[packName];
      await idbDeletePack(packName);

      setLoadedPackData((prev) => {
        const next = { ...prev };
        delete next[packName];
        return next;
      });
      setPackInfo((prev) => {
        const next = { ...prev };
        delete next[packName];
        return next;
      });

      // Rebuild the loaded icons without the deleted pack
      const remaining = { ...loadedPackData };
      delete remaining[packName];
      const activeIcons: any[] = [...coreIcons];
      Object.keys(remaining).forEach((id) => {
        const isActive = BUILTIN_PACKS.includes(id as IconPackName)
          ? enabledPacks.includes(id as IconPackName)
          : !disabledCustomPacks.includes(id);
        if (isActive) {
          activeIcons.push(...remaining[id]);
        }
      });
      setLoadedIcons(activeIcons);

      const newDisabled = disabledCustomPacks.filter((p) => {
        return p !== packName;
      });
      if (newDisabled.length !== disabledCustomPacks.length) {
        setDisabledCustomPacks(newDisabled);
        saveDisabledCustomPacks(newDisabled);
      }
    },
    [loadedPackData, enabledPacks, disabledCustomPacks, coreIcons]
  );

  // Initialize on mount:
  //   1. fetch the generated custom packs (icon-packs.generated.json)
  //   2. register them in packInfo
  //   3. load packs according to the lazy-loading preference:
  //        - lazy loading off  -> load everything
  //        - lazy loading on   -> built-ins: only the enabled ones
  //                               custom packs: all except explicitly disabled
  useEffect(() => {
    let cancelled = false;

    const initialize = async () => {
      const generated = await fetchCustomPacks();
      const importedPacks = await idbListPacks();
      if (cancelled) return;

      const customMap: Record<string, CustomPackDef> = {};
      generated?.forEach((p) => {
        customMap[p.id] = p;
      });
      importedPacks.forEach((p) => {
        if (!customMap[p.id]) {
          customMap[p.id] = p;
        }
      });
      customPacksRef.current = customMap;

      const customIds = Object.keys(customMap);
      if (customIds.length > 0) {
        setPackInfo((prev) => {
          const next = { ...prev };
          customIds.forEach((id) => {
            if (!next[id]) {
              next[id] = {
                name: id,
                displayName: customMap[id].name || id,
                loaded: false,
                loading: false,
                error: null,
                iconCount: 0,
                custom: true,
                imported: customMap[id].imported === true
              };
            }
          });
          return next;
        });
      }

      const shouldAutoLoad = (packId: string) => {
        if (!lazyLoadingEnabled) return true;
        if (BUILTIN_PACKS.includes(packId as IconPackName)) {
          return enabledPacks.includes(packId as IconPackName);
        }
        return !disabledCustomPacks.includes(packId);
      };

      const allIds = [...BUILTIN_PACKS, ...customIds];
      for (const id of allIds) {
        if (cancelled) return;
        if (shouldAutoLoad(id)) {
          try {
            await loadPackRef.current(id);
          } catch {
            // loadPack already recorded the error in packInfo
          }
        }
      }
    };

    initialize();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return {
    lazyLoadingEnabled,
    enabledPacks,
    /** Built-in packs the user switched on */
    enabledPackNames: enabledPacks,
    /** Built-ins enabled + custom packs (custom = on unless switched off) */
    effectiveEnabledPacks: [
      ...enabledPacks,
      ...Object.keys(packInfo).filter((id) => {
        return (
          packInfo[id].custom &&
          !disabledCustomPacks.includes(id)
        );
      })
    ],
    disabledCustomPacks,
    customPacks: customPacksRef.current,
    packInfo,
    loadedIcons,
    togglePack,
    toggleLazyLoading,
    loadAllPacks,
    loadPacksForDiagram,
    importIconFiles,
    deletePack,
    isPackEnabled: (packName: PackId) => {
      if (BUILTIN_PACKS.includes(packName as IconPackName)) {
        return enabledPacks.includes(packName as IconPackName);
      }
      return !disabledCustomPacks.includes(packName);
    }
  };
};
